// The recorded line for one vantage (or, with `kind`, one event, hotspot or
// barrier), or null if there isn't one.
export function narrationFor(slug, id, kind = 'vantage') {
  return SCENE_NARRATION[slug]?.[kind === 'vantage' ? id : `${kind}:${id}`] || null;
}
